const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define northwestern Pennsylvania region
  const nwPA = ee.Geometry.Polygon([
    [[-80.5, 41.8], [-79.5, 41.8], [-79.5, 41.2], [-80.5, 41.2], [-80.5, 41.8]]
  ]);

  // Date ranges
  const date1Start = '2020-02-20';
  const date1End = '2020-02-24';
  const date2Start = '2020-02-28';
  const date2End = '2020-03-03';

  // Function to calculate snow cover
  function getSnowMetrics(startDate, endDate, label) {
    let col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(nwPA)
      .filterDate(startDate, endDate)
      .map(function(img) {
        // Cloud mask
        const cloudMask = img.select('QA_PIXEL').bitwiseAnd(1 << 3).eq(0);
        // Calculate NDSI (snow index)
        const ndsi = img.normalizedDifference(['SR_B3', 'SR_B6']).rename('NDSI');
        return ndsi.updateMask(cloudMask);
      });

    const imgCount = col.size().getInfo();

    if (imgCount === 0) {
      console.log(`${label} Images: 0`);
      return null;
    }

    // Mosaic and calculate snow metrics
    const mosaic = col.median();
    const snowMask = mosaic.gte(0.4);

    const snowPixels = mosaic.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: nwPA,
      scale: 30,
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    const meanNDSI = mosaic.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: nwPA,
      scale: 30,
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    const snowCover = snowMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: nwPA,
      scale: 30,
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    console.log(`${label} - Images: ${imgCount}, Valid Pixels: ${snowPixels}, Mean NDSI: ${meanNDSI !== null ? meanNDSI.toFixed(3) : 'null'}, Snow Pixels: ${snowCover !== null ? snowCover : 0}`);

    return {
      snowCover: snowCover !== null ? snowCover : 0,
      meanNDSI: meanNDSI,
      validPixels: snowPixels
    };
  }

  // Get snow metrics for both periods
  const metrics1 = getSnowMetrics(date1Start, date1End, 'Feb 22, 2020');
  const metrics2 = getSnowMetrics(date2Start, date2End, 'Mar 1, 2020');

  // Validation and answer
  if (metrics1 === null) {
    console.log('No images for Feb 22 period');
    console.log('C1');
    return;
  }

  if (metrics2 === null) {
    console.log('No images for Mar 1 period');
    console.log('C1');
    return;
  }

  if (metrics1.validPixels === 0 || metrics2.validPixels === 0) {
    console.log('No valid pixels after cloud masking');
    console.log('C2');
    return;
  }

  if (metrics1.meanNDSI === null || metrics2.meanNDSI === null) {
    console.log('Calculation failed: null result');
    console.log('C3');
    return;
  }

  // Compare snow cover
  console.log(`Snow Cover Comparison: Feb22=${metrics1.snowCover}, Mar1=${metrics2.snowCover}`);

  if (metrics2.snowCover > metrics1.snowCover) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
